                    '[{"type":"function","name":"submitFeedback","inputSchema":{"type":"object","properties":{"targetType":{"type":"string","enum":["skill","mcp-tool","cli","docs","public-api","other"],"description":"Category of the thing the feedback is about."},"target":{"type":"string","minLength":1,"maxLength":200,"description":"The specific instance within targetType: the skill name, MCP tool name, CLI command, API endpoint path, or docs page path (e.g. \'queryMetrics\', \'/docs/mcp\'). An identifier, not a sentence."},"feedback":{"type":"string","minLength":1,"maxLength":3000},"goal":{"type":"string","minLength":1,"maxLength":1500},"referenceUrl":{"type":"string","format":"uri","maxLength":2048}},"required":["targetType","target","feedback"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"},"description":"Submit explicit user-approved feedback to the Langfuse team.\\nBefore calling, ask permission and show the exact payload.\\nDo not include secrets, credentials, customer data, trace payloads, or unrelated context."},{"type":"function","name":"searchLangfuseDocs","inputSchema":{"type":"object","properties":{"query":{"type":"string","description":"The user\'s question in natural language. Include helpful context like SDK/language (e.g., Python v3, JS v4), self-hosted vs cloud, and short error messages (trim long stack traces). Keep under ~600 characters."}},"required":["query"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"},"description":"Semantic search (RAG) over the Langfuse documentation. Use this whenever the user asks a broader question that cannot be answered by a specific single page. Returns a concise answer synthesized from relevant docs. The raw provider response is included in _meta. Prefer this before guessing. If a specific page is needed call getLangfuseDocsPage first."},{"type":"function","name":"getLangfuseDocsPage","inputSchema":{"type":"object","properties":{"pathOrUrl":{"type":"string","description":"Docs path starting with \\"/\\" (e.g., /docs/observability/overview) or a full URL on https://langfuse.com. Do not include anchors (#...) or queries (?foo=bar) — they will be ignored."}},"required":["pathOrUrl"],"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"},"description":"Fetch the raw Markdown for a single Langfuse docs page. Accepts a docs path (e.g., /docs/observability/overview) or a full https://langfuse.com URL. Returns the exact Markdown (may include front matter). Use when you need a specific page content (Integration, Features, API, etc.) or code samples. Prefer searchLangfuseDocs for broader questions where there is not one specific page about it. Changelog pages (/changelog/...) are historical release notes: use them only to confirm that a feature exists or when it shipped, not as an implementation reference. Their code samples reflect the SDK/API at release time and may be outdated, so for implementation follow the current docs and the API/SDK reference instead."},{"type":"function","name":"getLangfuseOverview","inputSchema":{"type":"object","properties":{},"additionalProperties":false,"$schema":"http://json-schema.org/draft-07/schema#"},"description":"Get a high-level, machine-readable index by downloading https://langfuse.com/llms.txt. Use this at the start of a session when needed to discover key docs endpoints or to seed follow-up calls to searchLangfuseDocs or getLangfuseDocsPage. Returns the plain text contents of llms.txt. Avoid repeated calls within the same session."}]',
